        new AuthManager({
          codexHome,
          validateStoredAuth: assertDomindsCodexProviderManagedChatGptStoredAuth,
        }),
    );
    assertPolicyError(error);
    assert.equal(fs.readFileSync(path.join(codexHome, 'auth.json'), 'utf8'), rawAuth);
