import path from 'node:path';

/** Only explicit AuthManager options use these profiles; HOME/CODEX_HOME stay user-owned. */
export function makeAuthProfile(): string {
  assert.equal(process.env.DOMINDS_TEST_RTWS_MANAGED, '1', 'run through tests/cli.ts');
  return fs.mkdtempSync(path.join(process.cwd(), '.auth-profile-'));
}
export function makeAuthJwt(payload: Record<string, unknown>): string {
  const encode = (value: unknown) => Buffer.from(JSON.stringify(value)).toString('base64url');
  return `${encode({ alg: 'none', typ: 'JWT' })}.${encode(payload)}.sig`;
}
export function captureAuthError(action: () => unknown): Error {
  let failure: unknown;
  try {
    action();
  } catch (error) {
    failure = error;
  }
  assert.ok(failure instanceof Error, 'the operation must reject');
  return failure;
}
export async function captureAsyncAuthError(action: () => Promise<unknown>): Promise<Error> {
  let failure: unknown;
  try {
    await action();
  } catch (error) {
    failure = error;
  }
  assert.ok(failure instanceof Error, 'the asynchronous operation must reject');
  return failure;
}

import fs from 'node:fs';
import path from 'node:path';

import { parseIdToken } from '../oauth/tokenParsing.js';
import type { StoredAuthSource } from './manager.js';
import type { AuthDotJson, AuthState, CodexStoredAuthMode } from './schema.js';
import { CODEX_ACCESS_TOKEN_ENV_VAR, resolveAuthDotJsonMode } from './schema.js';
import { readAuthFile, resolveCodexHome } from './storage.js';

export type CodexCliAuthStoreMode = 'file' | 'keyring' | 'auto' | 'ephemeral';

const CLI_AUTH_CREDENTIALS_STORE_ASSIGNMENT = 'cli_auth_credentials_store = "file"';
const CLI_AUTH_CREDENTIALS_STORE_PATTERN =
  /^[ \t]*cli_auth_credentials_store[ \t]*=[ \t]*(?:"([^"]*)"|'([^']*)'|([A-Za-z0-9_-]+))[ \t]*(?:#.*)?$/m;
const DOMINDS_FEATURE_REQUEST_URL = 'https://github.com/longrun-ai/dominds/issues';

export const DOMINDS_CODEX_PROVIDER_AUTH_POLICY =
  'The Dominds codex provider supports only managed ChatGPT OAuth file auth.';
export const DOMINDS_CODEX_PROVIDER_AUTH_POLICY_ERROR_CODE = 'DOMINDS_CODEX_PROVIDER_AUTH_POLICY';

export class DomindsCodexProviderAuthPolicyError extends Error {
  readonly code = DOMINDS_CODEX_PROVIDER_AUTH_POLICY_ERROR_CODE;

  constructor(message: string) {
    super(message);
    this.name = 'DomindsCodexProviderAuthPolicyError';
  }
}

export type CodexFileAuthPreparationResult =
  | {
      kind: 'ready';
      codexHome: string;
      configPath: string;
      changedConfigToFile: boolean;
      previousStoreMode?: CodexCliAuthStoreMode;
    }
  | {
      kind: 'action_required';
      codexHome: string;
      configPath: string;
      reason:
        | 'config_write_failed'
        | 'invalid_file_auth'
        | 'missing_file_auth'
        | 'api_key_auth'
        | 'unsupported_auth_mode'
        | 'incomplete_chatgpt_auth';
      message: string;
      steps: string[];
      changedConfigToFile: boolean;
      previousStoreMode?: CodexCliAuthStoreMode;
    };

export interface PrepareCodexFileAuthOptions {
  codexHome?: string;
  codexHomeEnvVar?: string;
  providerName?: string;
}

export interface CodexCliAuthStoreModeConfig {
  configPath: string;
  mode?: CodexCliAuthStoreMode;
}

export function readCodexCliAuthStoreMode(codexHome: string): CodexCliAuthStoreModeConfig {
  const configPath = codexConfigPath(codexHome);
  if (!fs.existsSync(configPath)) {
    return { configPath };
  }

  const raw = fs.readFileSync(configPath, 'utf8');
  const match = topLevelTomlPrefix(raw).match(CLI_AUTH_CREDENTIALS_STORE_PATTERN);
  if (!match) {
    return { configPath };
  }

  const mode = parseStoreMode(match[1] ?? match[2] ?? match[3] ?? '');
  return mode === undefined ? { configPath } : { configPath, mode };
}

export function setCodexCliAuthStoreModeToFile(codexHome: string): {
  configPath: string;
  previousStoreMode?: CodexCliAuthStoreMode;
  changed: boolean;
} {
  const configPath = codexConfigPath(codexHome);
  const before = readCodexCliAuthStoreMode(codexHome);
  if (before.mode === 'file') {
    return { configPath, previousStoreMode: before.mode, changed: false };
  }

  let raw = '';
  if (fs.existsSync(configPath)) {
    raw = fs.readFileSync(configPath, 'utf8');
  }

  const topLevel = topLevelTomlPrefix(raw);
  const nextRaw = CLI_AUTH_CREDENTIALS_STORE_PATTERN.test(topLevel)
    ? raw.replace(CLI_AUTH_CREDENTIALS_STORE_PATTERN, CLI_AUTH_CREDENTIALS_STORE_ASSIGNMENT)
    : prependTopLevelTomlAssignment(raw, CLI_AUTH_CREDENTIALS_STORE_ASSIGNMENT);

  fs.mkdirSync(codexHome, { recursive: true });
  fs.writeFileSync(configPath, nextRaw, { mode: 0o600 });
  return {
    configPath,
    previousStoreMode: before.mode,
    changed: true,
  };
}

export function prepareCodexFileAuth(
  options: PrepareCodexFileAuthOptions = {},
): CodexFileAuthPreparationResult {
  const codexHome = resolveCodexHome(options.codexHome);
  const providerName = options.providerName ?? 'Dominds codex provider';

  let configPath = codexConfigPath(codexHome);
  let previousStoreMode: CodexCliAuthStoreMode | undefined;
  let changedConfigToFile = false;

  const codexAccessToken = process.env[CODEX_ACCESS_TOKEN_ENV_VAR]?.trim();
  if (codexAccessToken) {
    const detectedMode = codexAccessToken.startsWith('at-')
      ? 'personalAccessToken via CODEX_ACCESS_TOKEN'
      : 'agentIdentity via CODEX_ACCESS_TOKEN';
    return actionRequired({
      codexHome,
      configPath,
      reason: 'unsupported_auth_mode',
      changedConfigToFile,
      message: formatDomindsCodexProviderUnsupportedAuth(detectedMode),
      steps: unsupportedAuthSteps(codexHome, options.codexHomeEnvVar, true),
    });
  }

  try {
    const change = setCodexCliAuthStoreModeToFile(codexHome);
    configPath = change.configPath;
    previousStoreMode = change.previousStoreMode;
    changedConfigToFile = change.changed;
  } catch (err: unknown) {
    const details = err instanceof Error ? err.message : String(err);
    return actionRequired({
      codexHome,
      configPath,
      reason: 'config_write_failed',
      changedConfigToFile,
      previousStoreMode,
      message: `${providerName} requires Codex CLI auth to be stored in file mode, but Dominds could not update ${configPath}: ${details}`,
      steps: fileModeSteps(codexHome, options.codexHomeEnvVar),
    });
  }

  let auth: AuthDotJson | null;
  try {
    auth = readAuthFile(codexHome, 'file');
  } catch (err: unknown) {
    const details = err instanceof Error ? err.message : String(err);
    return actionRequired({
      codexHome,
      configPath,
      reason: 'invalid_file_auth',
      changedConfigToFile,
      previousStoreMode,
      message: `${providerName} could not read ${path.join(codexHome, 'auth.json')}: ${details}`,
      steps: loginSteps(codexHome, options.codexHomeEnvVar),
    });
  }
  if (!auth) {
    const movedFrom =
      previousStoreMode && previousStoreMode !== 'file'
        ? ` Codex was configured for ${previousStoreMode} auth storage; Dominds switched the config to file mode, but cannot extract existing secrets from ${previousStoreMode} storage.`
        : '';
    return actionRequired({
      codexHome,
      configPath,
      reason: 'missing_file_auth',
      changedConfigToFile,
      previousStoreMode,
      message: `${providerName} needs ChatGPT OAuth tokens in ${path.join(codexHome, 'auth.json')}.${movedFrom}`,
      steps: loginSteps(codexHome, options.codexHomeEnvVar),
    });
  }

  let mode: CodexStoredAuthMode;
  try {
    mode = resolveAuthDotJsonMode(auth);
  } catch (err: unknown) {
    const details = err instanceof Error ? err.message : String(err);
    return actionRequired({
      codexHome,
      configPath,
      reason: 'unsupported_auth_mode',
      changedConfigToFile,
      previousStoreMode,
      message: `${providerName} cannot use the current Codex auth: ${details} ${formatDomindsCodexProviderUnsupportedAuth('unknown auth.json mode')}`,
      steps: unsupportedAuthSteps(codexHome, options.codexHomeEnvVar, false),
    });
  }

  const chatgptIssue = validateChatgptAuth(mode, auth);
  if (chatgptIssue !== undefined) {
    const { reason, message } = chatgptIssue;
    const unsupportedMode = reason === 'api_key_auth' || reason === 'unsupported_auth_mode';
    return actionRequired({
      codexHome,
      configPath,
      reason,
      changedConfigToFile,
      previousStoreMode,
      message: `${providerName} cannot use the current Codex auth: ${message}`,
      steps: unsupportedMode
        ? unsupportedAuthSteps(codexHome, options.codexHomeEnvVar, false)
        : loginSteps(codexHome, options.codexHomeEnvVar),
    });
  }

  return {
    kind: 'ready',
    codexHome,
    configPath,
    changedConfigToFile,
    previousStoreMode,
  };
}

export function formatCodexFileAuthActionRequired(
  result: Extract<CodexFileAuthPreparationResult, { kind: 'action_required' }>,
): string {
  return [
    result.message,
    '',
    'Recommended steps:',
    ...result.steps.map((step, idx) => `${idx + 1}. ${step}`),
  ].join('\n');
}

export function formatDomindsCodexProviderUnsupportedAuth(detectedMode: string): string {
  return `${DOMINDS_CODEX_PROVIDER_AUTH_POLICY} Detected ${detectedMode}. To use another authentication method, configure a custom Dominds OpenAI Responses API provider (apiType: openai), or submit a Dominds feature request at ${DOMINDS_FEATURE_REQUEST_URL}.`;
}

export function assertDomindsCodexProviderManagedChatGptAuth(
  auth: AuthState | null,
): asserts auth is Extract<AuthState, { mode: 'chatgpt' }> {
  if (auth?.mode !== 'chatgpt') {
    throw new DomindsCodexProviderAuthPolicyError(
      formatDomindsCodexProviderUnsupportedAuth(auth?.mode ?? 'missing auth'),
    );
  }

  const tokens = auth.tokens;
  if (
    !isNonEmptyString(tokens.idToken.raw_jwt) ||
    !isNonEmptyString(tokens.accessToken) ||
    !isNonEmptyString(tokens.refreshToken) ||
    !isNonEmptyString(tokens.accountId)
  ) {
    throw new DomindsCodexProviderAuthPolicyError(
      formatDomindsCodexProviderInvalidManagedAuth(
        'The loaded ChatGPT auth state is missing an id token, access token, refresh token, or account id.',
      ),
    );
  }
}

export function assertDomindsCodexProviderManagedChatGptStoredAuth(
  auth: AuthDotJson,
  source: StoredAuthSource,
): void {
  let mode: CodexStoredAuthMode;
  try {
    mode = resolveAuthDotJsonMode(auth);
  } catch {
    throw new DomindsCodexProviderAuthPolicyError(
      formatDomindsCodexProviderUnsupportedAuth('unknown auth.json mode'),
    );
  }
  if (source !== 'persistent') {
    throw new DomindsCodexProviderAuthPolicyError(
      formatDomindsCodexProviderUnsupportedAuth(`${mode} from the ephemeral auth store`),
    );
  }
  if (mode !== 'chatgpt') {
    throw new DomindsCodexProviderAuthPolicyError(
      formatDomindsCodexProviderUnsupportedAuth(`${mode} in auth.json`),
    );
  }

  const issue = validateChatgptAuth(mode, auth);
  if (issue !== undefined) {
    throw new DomindsCodexProviderAuthPolicyError(
      formatDomindsCodexProviderInvalidManagedAuth(issue.message),
    );
  }
}

function formatDomindsCodexProviderInvalidManagedAuth(details: string): string {
  return `${DOMINDS_CODEX_PROVIDER_AUTH_POLICY} ${details} Re-run Codex ChatGPT login in file mode. To use another authentication method, configure a custom Dominds OpenAI Responses API provider (apiType: openai), or submit a Dominds feature request at ${DOMINDS_FEATURE_REQUEST_URL}.`;
}

function validateChatgptAuth(
  mode: CodexStoredAuthMode,
  auth: AuthDotJson,
):
  | {
      reason: Extract<CodexFileAuthPreparationResult, { kind: 'action_required' }>['reason'];
      message: string;
    }
  | undefined {
  switch (mode) {
    case 'chatgpt':
      break;
    case 'apikey':
      return {
        reason: 'api_key_auth',
        message: formatDomindsCodexProviderUnsupportedAuth('apikey in auth.json'),
      };
    case 'chatgptAuthTokens':
      return {
        reason: 'unsupported_auth_mode',
        message: formatDomindsCodexProviderUnsupportedAuth('chatgptAuthTokens in auth.json'),
      };
    case 'headers':
      return {
        reason: 'unsupported_auth_mode',
        message: formatDomindsCodexProviderUnsupportedAuth('headers auth'),
      };
    case 'agentIdentity':
      return {
        reason: 'unsupported_auth_mode',
        message: formatDomindsCodexProviderUnsupportedAuth('agentIdentity in auth.json'),
      };
    case 'personalAccessToken':
      return {
        reason: 'unsupported_auth_mode',
        message: formatDomindsCodexProviderUnsupportedAuth('personalAccessToken in auth.json'),
      };
    case 'bedrockApiKey':
      return {
        reason: 'unsupported_auth_mode',
        message: formatDomindsCodexProviderUnsupportedAuth('bedrockApiKey in auth.json'),
      };
    default: {
      const _exhaustive: never = mode;
      throw new Error(`Unhandled Codex stored auth mode: ${String(_exhaustive)}`);
    }
  }

  const tokens = auth.tokens;
  if (
    !tokens ||
    !isNonEmptyString(tokens.id_token) ||
    !isNonEmptyString(tokens.access_token) ||
    !isNonEmptyString(tokens.refresh_token)
  ) {
    return {
      reason: 'incomplete_chatgpt_auth',
      message:
        'auth.json declares ChatGPT auth but is missing id_token, access_token, or refresh_token.',
    };
  }

  let idTokenInfo: ReturnType<typeof parseIdToken>;
  try {
    idTokenInfo = parseIdToken(tokens.id_token);
  } catch (err: unknown) {
    const details = err instanceof Error ? err.message : String(err);
    return {
      reason: 'invalid_file_auth',
      message: `auth.json contains an invalid ChatGPT id_token: ${details}`,
    };
  }

  if (!isNonEmptyString(tokens.account_id) && !isNonEmptyString(idTokenInfo.chatgpt_account_id)) {
    return {
      reason: 'incomplete_chatgpt_auth',
      message:
        'auth.json ChatGPT tokens do not include a ChatGPT account id. Re-run Codex login so auth.json can be regenerated.',
    };
  }
  return undefined;
}

function actionRequired(
  result: Omit<Extract<CodexFileAuthPreparationResult, { kind: 'action_required' }>, 'kind'>,
): CodexFileAuthPreparationResult {
  return { kind: 'action_required', ...result };
}

function codexConfigPath(codexHome: string): string {
  return path.join(codexHome, 'config.toml');
}

function parseStoreMode(value: string): CodexCliAuthStoreMode | undefined {
  const normalized = value.trim().toLowerCase();
  if (
    normalized === 'file' ||
    normalized === 'keyring' ||
    normalized === 'auto' ||
    normalized === 'ephemeral'
  ) {
    return normalized;
  }
  return undefined;
}

function prependTopLevelTomlAssignment(raw: string, assignment: string): string {
  if (raw.length === 0) {
    return `${assignment}\n`;
  }
  return `${assignment}\n${raw}`;
}

function topLevelTomlPrefix(raw: string): string {
  const tableMatch = raw.match(/^[ \t]*(?:\[\[[^\]]+\]\]|\[[^\]]+\])[ \t]*(?:#.*)?$/m);
  if (!tableMatch || tableMatch.index === undefined) {
    return raw;
  }
  return raw.slice(0, tableMatch.index);
}

function fileModeSteps(codexHome: string, codexHomeEnvVar: string | undefined): string[] {
  const envPrefix =
    `CODEX_HOME=${shellQuote(codexHome)} ` +
    (codexHomeEnvVar && codexHomeEnvVar !== 'CODEX_HOME'
      ? `${codexHomeEnvVar}=${shellQuote(codexHome)} `
      : '');
  return [
    `Set Codex CLI auth storage to file mode: ${envPrefix}codex -c cli_auth_credentials_store=file login status`,
    `Or edit ${codexConfigPath(codexHome)} and add: cli_auth_credentials_store = "file"`,
  ];
}

function loginSteps(codexHome: string, codexHomeEnvVar: string | undefined): string[] {
  const envPrefix =
    `CODEX_HOME=${shellQuote(codexHome)} ` +
    (codexHomeEnvVar && codexHomeEnvVar !== 'CODEX_HOME'
      ? `${codexHomeEnvVar}=${shellQuote(codexHome)} `
      : '');
  return [
    `Run ChatGPT login in file mode: ${envPrefix}codex -c cli_auth_credentials_store=file login`,
    `Verify file auth exists: ${envPrefix}codex -c cli_auth_credentials_store=file login status`,
    `Then retry Dominds. Expected file: ${path.join(codexHome, 'auth.json')}`,
  ];
}

function unsupportedAuthSteps(
  codexHome: string,
  codexHomeEnvVar: string | undefined,
  unsetCodexAccessToken: boolean,
): string[] {
  const steps = unsetCodexAccessToken
    ? [
        `Unset ${CODEX_ACCESS_TOKEN_ENV_VAR}; the Dominds codex provider does not consume PAT or Agent Identity credentials.`,
      ]
    : [];
  return [
    ...steps,
    ...loginSteps(codexHome, codexHomeEnvVar),
    'If another authentication method is intentional, configure a custom Dominds OpenAI Responses API provider with apiType: openai.',
    `If that provider cannot cover the required authentication flow, submit a Dominds feature request: ${DOMINDS_FEATURE_REQUEST_URL}`,
  ];
}

function shellQuote(value: string): string {
  return `'${value.replaceAll("'", "'\\''")}'`;
}

function isNonEmptyString(value: unknown): value is string {
  return typeof value === 'string' && value.trim().length > 0;
}

finalRefreshGenerationSources.text:
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

import {
  AuthManager,
  CODEX_ACCESS_TOKEN_ENV_VAR,
  CODEX_APP_SERVER_LOGIN_CLIENT_ID_ENV_VAR,
  CODEX_REFRESH_TOKEN_URL_OVERRIDE_ENV_VAR,
  RefreshTokenError,
  readAuthFile,
  tryRefreshToken,
  withAuthRefreshFileLock,
  writeAuthFile,
} from '../codex-auth/src/index';

import {
  captureAsyncAuthError,
  makeAuthProfile as makeCodexHome,
  makeAuthJwt as makeJwt,
} from './helpers/auth-fixture';
import { semanticEvidenceCollector } from './helpers/semantic-evidence';
const evidence = semanticEvidenceCollector('dominds-codex-auth-refresh-');
const requests: Array<{
  url: string;
  expectedRefreshToken: string;
  method: string | undefined;
  headers: Record<string, string>;
  body: string | undefined;
}> = [];
const endpoint = 'https://auth.test/oauth/token';
function diagnostic(
  id: string,
  scenario: string,
  error: Error,
  context: Record<string, string | number | boolean>,
) {
  evidence.record({
    id,
    scenario,
    businessValue:
      'A caller must distinguish a transient outage from exhausted refresh credentials and choose a recovery action without losing stored state.',
    context,
    reviewQuestions: [
      'Does the complete diagnostic accurately convey the supplied failure and give usable recovery guidance without misclassifying it?',
    ],
    actualText: error.message,
  });
}

type FetchHandler = (input: RequestInfo | URL, init?: RequestInit) => Promise<Response>;

const ACCOUNT_ID = 'acct_test';

async function run(): Promise<void> {
  assert.equal(process.env.DOMINDS_TEST_RTWS_MANAGED, '1');
  const originalAccessToken = process.env[CODEX_ACCESS_TOKEN_ENV_VAR];
  delete process.env[CODEX_ACCESS_TOKEN_ENV_VAR];
  const originalFetch = globalThis.fetch;
  const originalClientId = process.env[CODEX_APP_SERVER_LOGIN_CLIENT_ID_ENV_VAR];
  process.env[CODEX_APP_SERVER_LOGIN_CLIENT_ID_ENV_VAR] = 'controlled-client-id';
  const originalRefreshUrl = process.env[CODEX_REFRESH_TOKEN_URL_OVERRIDE_ENV_VAR];
  process.env[CODEX_REFRESH_TOKEN_URL_OVERRIDE_ENV_VAR] = endpoint;

  try {
    await testConcurrentRefreshesShareSingleRequest();
    await testFileLockRereadsDiskAndSkipsRefresh();
    await testStaleFileLockIsCleanedBeforeAcquire();
    await testStaleLockFileIsCleanedBeforeAcquire();
    await testFreshReaperLockBlocksAcquire();
    await testActiveLocalOwnerBlocksStaleCleanup();
    await testLockReleaseDoesNotRemoveReplacementOwner();
    await testExpiredTokenRefreshesOnAuth();
    await testNearExpiryTransientRefreshFailureUsesOldToken();
    await testExpiredTransientRefreshFailureFails();
    await testStructuredPermanentRefreshErrorOnNon401();
  } finally {
    globalThis.fetch = originalFetch;
    if (originalAccessToken === undefined) delete process.env[CODEX_ACCESS_TOKEN_ENV_VAR];
    else process.env[CODEX_ACCESS_TOKEN_ENV_VAR] = originalAccessToken;
    if (originalClientId === undefined)
      delete process.env[CODEX_APP_SERVER_LOGIN_CLIENT_ID_ENV_VAR];
    else process.env[CODEX_APP_SERVER_LOGIN_CLIENT_ID_ENV_VAR] = originalClientId;
    if (originalRefreshUrl === undefined) {
      delete process.env[CODEX_REFRESH_TOKEN_URL_OVERRIDE_ENV_VAR];
    } else {
      process.env[CODEX_REFRESH_TOKEN_URL_OVERRIDE_ENV_VAR] = originalRefreshUrl;
    }
  }

  for (const request of requests) {
    assert.equal(request.url, endpoint);
    assert.equal(request.method, 'POST');
    assert.equal(request.headers['content-type'], 'application/json');
    assert.ok(typeof request.body === 'string');
    const body: unknown = JSON.parse(request.body);
    assert.ok(
      body &&
        typeof body === 'object' &&
        'client_id' in body &&
        'grant_type' in body &&
        'refresh_token' in body,
    );
    assert.equal(body.client_id, 'controlled-client-id');
    assert.equal(body.grant_type, 'refresh_token');
    assert.equal(body.refresh_token, request.expectedRefreshToken);
  }
  await evidence.write();
  console.log('codex-auth refresh tests: ok');
}

async function testConcurrentRefreshesShareSingleRequest(): Promise<void> {
  const codexHome = makeCodexHome();
  const oldAccess = makeAccessToken('old-access', 60);
  const newAccess = makeAccessToken('new-access', 3600);
  const newId = makeIdToken();
  writeManagedAuth(codexHome, oldAccess, 'old-refresh');

  let requestCount = 0;
  let markEntered: () => void = () => {
    throw new Error('request gate not initialized');
  };
  let releaseResponse: () => void = () => {
    throw new Error('response gate not initialized');
  };
  const entered = new Promise<void>((resolve) => {
    markEntered = resolve;
  });
  const release = new Promise<void>((resolve) => {
    releaseResponse = resolve;
  });
  installFetchMock('old-refresh', async () => {
    requestCount += 1;
    markEntered();
    await release;
    return jsonResponse(200, {
      id_token: newId,
      access_token: newAccess,
      refresh_token: 'new-refresh',
    });
  });

  const managers = [
    new AuthManager({ codexHome }),
    new AuthManager({ codexHome }),
    new AuthManager({ codexHome }),
  ];
  const running = Promise.all(managers.map((manager) => manager.auth()));
  await entered;
  releaseResponse();
  await running;

  assert.equal(requestCount, 1, 'concurrent refreshes should call the token endpoint once');
  assert.deepEqual(
    managers.map((manager) => manager.getToken()),
    [newAccess, newAccess, newAccess],
  );
  assert.equal(readAuthFile(codexHome)?.tokens?.refresh_token, 'new-refresh');
  assert.equal(fs.existsSync(path.join(codexHome, 'auth-refresh.lock')), false);
}

async function testFileLockRereadsDiskAndSkipsRefresh(): Promise<void> {
  const codexHome = makeCodexHome();
  const oldAccess = makeAccessToken('old-access', 60);
  const newAccess = makeAccessToken('lock-refreshed-access', 3600);
  writeManagedAuth(codexHome, oldAccess, 'old-refresh');

  let requestCount = 0;
  installFetchMock('old-refresh', async () => {
    requestCount += 1;
    return jsonResponse(200, {
      id_token: makeIdToken(),
      access_token: makeAccessToken('unexpected-access', 3600),
      refresh_token: 'unexpected-refresh',
    });
  });

  const manager = new AuthManager({ codexHome });
  let refreshPromise: Promise<void> | undefined;
  await withAuthRefreshFileLock(codexHome, async () => {
    refreshPromise = manager.refreshTokenFromAuthority();
    writeManagedAuth(codexHome, newAccess, 'lock-refreshed-token');
  });
  if (!refreshPromise) {
    throw new Error('refresh promise was not started');
  }
  await refreshPromise;

  assert.equal(requestCount, 0, 'refresh should be skipped when the locked file changed first');
  assert.equal(manager.getToken(), newAccess);
  assert.equal(readAuthFile(codexHome)?.tokens?.refresh_token, 'lock-refreshed-token');
  assert.equal(fs.existsSync(path.join(codexHome, 'auth-refresh.lock')), false);
}

async function testStaleFileLockIsCleanedBeforeAcquire(): Promise<void> {
  const owners = [
    { pid: 1, hostname: 'stale-host', createdAt: new Date(0).toISOString() },
    {
      lockId: 'complete-stale-foreign-owner',
      pid: 1,
      hostname: 'stale-host',
      createdAt: new Date(0).toISOString(),
    },
  ];
  for (const owner of owners) {
    const codexHome = makeCodexHome();
    const lockPath = path.join(codexHome, 'auth-refresh.lock');
    const reaperLockPath = lockPath + '.reaper';
    const ownerPath = path.join(lockPath, 'owner.json');
    fs.mkdirSync(lockPath);
    fs.mkdirSync(reaperLockPath);
    fs.writeFileSync(ownerPath, JSON.stringify(owner), { encoding: 'utf8', mode: 0o600 });
    const staleTime = new Date(Date.now() - 3 * 60 * 1000);
    for (const file of [ownerPath, lockPath, reaperLockPath])
      fs.utimesSync(file, staleTime, staleTime);
    let acquired = false;
    await withAuthRefreshFileLock(codexHome, async () => {
      acquired = true;
      const current: unknown = JSON.parse(fs.readFileSync(ownerPath, 'utf8'));
      assert.ok(
        current &&
          typeof current === 'object' &&
          'pid' in current &&
          'hostname' in current &&
          'lockId' in current,
      );
      assert.equal(current.pid, process.pid);
      assert.equal(current.hostname, os.hostname());
      assert.ok(typeof current.lockId === 'string' && current.lockId.length > 0);
    });
    assert.equal(acquired, true);
    assert.equal(fs.existsSync(lockPath), false);
    assert.equal(fs.existsSync(reaperLockPath), false);
  }
}

async function testStaleLockFileIsCleanedBeforeAcquire(): Promise<void> {
  const codexHome = makeCodexHome();
  const lockPath = path.join(codexHome, 'auth-refresh.lock');
  fs.writeFileSync(lockPath, 'stale lock file', { encoding: 'utf8', mode: 0o600 });
  const staleTime = new Date(Date.now() - 3 * 60 * 1000);
  fs.utimesSync(lockPath, staleTime, staleTime);

  let acquired = false;
  await withAuthRefreshFileLock(codexHome, async () => {
    acquired = true;
  });

  assert.equal(acquired, true);
  assert.equal(fs.existsSync(lockPath), false);
}

async function testFreshReaperLockBlocksAcquire(): Promise<void> {
  const codexHome = makeCodexHome();
  const lockPath = path.join(codexHome, 'auth-refresh.lock');
  const reaperLockPath = `${lockPath}.reaper`;
  fs.mkdirSync(reaperLockPath);

  let acquired = false;
  const acquirePromise = withAuthRefreshFileLock(codexHome, async () => {
    acquired = true;
  });
  assert.equal(acquired, false, 'fresh reaper lock should block new refresh lock acquisition');
  assert.equal(fs.existsSync(reaperLockPath), true, 'a fresh reaper cannot be removed');
  assert.equal(
    fs.existsSync(lockPath),
    false,
    'the refresh lock cannot be claimed while the reaper is present',
  );
  fs.rmSync(reaperLockPath, { recursive: true, force: true });
  await acquirePromise;

  assert.equal(acquired, true);
  assert.equal(fs.existsSync(lockPath), false);
}

async function testActiveLocalOwnerBlocksStaleCleanup(): Promise<void> {
  const codexHome = makeCodexHome();
  const lockPath = path.join(codexHome, 'auth-refresh.lock');
  const ownerPath = path.join(lockPath, 'owner.json');
  fs.mkdirSync(lockPath);
  fs.writeFileSync(
    ownerPath,
    JSON.stringify({
      lockId: 'active-local-lock',
      pid: process.pid,
      hostname: os.hostname(),
      createdAt: new Date(0).toISOString(),
    }),
    { encoding: 'utf8', mode: 0o600 },
  );
  const staleTime = new Date(Date.now() - 3 * 60 * 1000);
  fs.utimesSync(ownerPath, staleTime, staleTime);
  fs.utimesSync(lockPath, staleTime, staleTime);

  const originalOwner = fs.readFileSync(ownerPath, 'utf8');
  let acquired = false;
  const acquirePromise = withAuthRefreshFileLock(codexHome, async () => {
    acquired = true;
  });
  assert.equal(
    fs.readFileSync(ownerPath, 'utf8'),
    originalOwner,
    'a live local owner must retain its lock record',
  );
  assert.equal(acquired, false, 'active local owner should prevent stale lock cleanup');
  fs.rmSync(lockPath, { recursive: true, force: true });
  await acquirePromise;

  assert.equal(acquired, true);
  assert.equal(fs.existsSync(lockPath), false);
}

async function testLockReleaseDoesNotRemoveReplacementOwner(): Promise<void> {
  const codexHome = makeCodexHome();
  const lockPath = path.join(codexHome, 'auth-refresh.lock');
  const replacementOwner = {
    lockId: 'replacement-lock',
    pid: 123,
    hostname: 'replacement-host',
    createdAt: new Date().toISOString(),
  };

  await withAuthRefreshFileLock(codexHome, async () => {
    fs.rmSync(lockPath, { recursive: true, force: true });
    fs.mkdirSync(lockPath);
    fs.writeFileSync(path.join(lockPath, 'owner.json'), JSON.stringify(replacementOwner), {
      encoding: 'utf8',
      mode: 0o600,
    });
  });

  assert.equal(fs.existsSync(lockPath), true);
  assert.deepEqual(
    JSON.parse(fs.readFileSync(path.join(lockPath, 'owner.json'), 'utf8')) as unknown,
    replacementOwner,
  );
  fs.rmSync(lockPath, { recursive: true, force: true });
}

async function testExpiredTokenRefreshesOnAuth(): Promise<void> {
  const codexHome = makeCodexHome();
  const newAccess = makeAccessToken('fresh-access', 3600);
  writeManagedAuth(codexHome, makeAccessToken('expired-access', -60), 'expired-refresh');

  let requestCount = 0;
  installFetchMock('expired-refresh', async () => {
    requestCount += 1;
    return jsonResponse(200, {
      id_token: makeIdToken(),
      access_token: newAccess,
      refresh_token: 'fresh-refresh',
    });
  });

  const manager = new AuthManager({ codexHome });
  await manager.auth();

  assert.equal(requestCount, 1);
  assert.equal(manager.getToken(), newAccess);
  assert.equal(readAuthFile(codexHome)?.tokens?.refresh_token, 'fresh-refresh');
}

async function testNearExpiryTransientRefreshFailureUsesOldToken(): Promise<void> {
  const codexHome = makeCodexHome();
  const oldAccess = makeAccessToken('near-expiry-access', 60);
  writeManagedAuth(codexHome, oldAccess, 'near-expiry-refresh');

  let requestCount = 0;
  installFetchMock('near-expiry-refresh', async () => {
    requestCount += 1;
    return jsonResponse(500, { error: { message: 'try again later' } });
  });

  const manager = new AuthManager({ codexHome });
  const auth = await manager.auth();

  assert.equal(requestCount, 1);
  assert.equal(auth?.mode, 'chatgpt');
  assert.equal(manager.getToken(), oldAccess);
  assert.equal(readAuthFile(codexHome)?.tokens?.refresh_token, 'near-expiry-refresh');
}

async function testExpiredTransientRefreshFailureFails(): Promise<void> {
  const codexHome = makeCodexHome();
  writeManagedAuth(codexHome, makeAccessToken('expired-access', -60), 'expired-refresh');

  let requestCount = 0;
  installFetchMock('expired-refresh', async () => {
    requestCount += 1;
    return jsonResponse(503, { error: { message: 'temporarily unavailable' } });
  });

  const manager = new AuthManager({ codexHome });
  const before = fs.readFileSync(path.join(codexHome, 'auth.json'), 'utf8');
  const error = await captureAsyncAuthError(() => manager.auth());
  assert.ok(error instanceof RefreshTokenError);
  assert.equal(error.kind, 'transient');
  assert.equal(fs.readFileSync(path.join(codexHome, 'auth.json'), 'utf8'), before);
  diagnostic(
    'expired-transient-refresh',
