function tamperDownloadedRecord(zip:Buffer,url:URL):Buffer {
 if(url.pathname!=='/api/dialog-forensics.zip' || !url.searchParams.has('selfId') || url.searchParams.has('mode')) return zip;
 const entries=readZipEntries(zip);const original=entries.get('manifest.json');const wrong=entries.get('side/nested/comma,name.json');const target=entries.get('side/latest.yaml');
 assert.ok(original && wrong && target);assert.equal(wrong.length,target.length);
 const manifest=record(JSON.parse(original.toString('utf8')) as unknown);assert.ok(Array.isArray(manifest.files));
 const targetMeta=record(manifest.files.find(item=>record(item).entryName==='side/latest.yaml'));
 const wrongMeta=record(manifest.files.find(item=>record(item).entryName==='side/nested/comma,name.json'));
 targetMeta.sourcePath=wrongMeta.sourcePath;targetMeta.size=wrong.length;
 const compact=JSON.stringify(manifest);const padding=original.length-Buffer.byteLength(compact);assert.ok(padding>=0);
 const replacements=new Map([['side/latest.yaml',wrong],['manifest.json',Buffer.from(compact+' '.repeat(padding))]]);
 const result=Buffer.from(zip);const end=result.length-22;assert.equal(result.readUInt32LE(end),0x06054b50);
 let offset=result.readUInt32LE(end+16);const count=result.readUInt16LE(end+10);
 for(let index=0;index<count;index++) {
  const nameLength=result.readUInt16LE(offset+28),extraLength=result.readUInt16LE(offset+30),commentLength=result.readUInt16LE(offset+32);
  const name=result.subarray(offset+46,offset+46+nameLength).toString('utf8');const replacement=replacements.get(name);
  if(replacement) {
   const local=result.readUInt32LE(offset+42);const start=local+30+result.readUInt16LE(local+26)+result.readUInt16LE(local+28);
   assert.equal(result.readUInt16LE(local+8),0);assert.equal(replacement.length,result.readUInt32LE(offset+24));
   replacement.copy(result,start);const checksum=crc32(replacement);result.writeUInt32LE(checksum,offset+16);result.writeUInt32LE(checksum,local+14);
  }
  offset+=46+nameLength+extraLength+commentLength;
 }
 writeFileSync(path.join(process.cwd(),'injected-misrouted-forensics.zip'),result);
 return result;
}

